  HF.addChapter({
    id: 'groups-fx',
    part: 'p4',
    title: 'Group Accounts & Foreign Currency',
    subtitle: 'When one company owns another — and when money crosses borders',
    art: 'globe',
    level: 'Advanced',
    minutes: 35,
    quote: 'A group is one economic entity wearing many legal hats.',
    goals: ['Explain control, subsidiaries, associates and joint arrangements', 'Calculate goodwill and non-controlling interest', 'Eliminate intercompany transactions and unrealised profit', 'Account for foreign currency transactions and translation'],
    blocks: [
      { t: 'h', text: 'Who’s in the family?' },
      {
        t: 'table',
        head: ['Relationship', 'Typical holding', 'Test', 'Accounting'],
        rows: [
          ['Subsidiary', '> 50%', '<b>Control</b>: power + variable returns + ability to use power (IFRS 10)', 'Full consolidation, line by line'],
          ['Associate', '20%–50%', '<b>Significant influence</b> (IAS 28)', 'Equity method: one line, share of profit'],
          ['Joint venture', 'Shared', '<b>Joint control</b>, rights to net assets (IFRS 11)', 'Equity method'],
          ['Joint operation', 'Shared', 'Joint control, rights to assets/obligations for liabilities', 'Own share of assets, liabilities, revenue, expenses'],
          ['Simple investment', '< 20%', 'No influence', 'Financial instrument (IFRS 9) at fair value'],
        ],
      },
      { t: 'sticky', html: 'Percentages are just hints. <b>Control</b> can exist with 40% (e.g., other holders are scattered) or be absent at 60% (e.g., a contract gives power to someone else).' },

      { t: 'h', text: 'Consolidation step by step' },
      { t: 'steps', items: [{ t: 'Add everything up', d: 'Parent + 100% of each subsidiary’s assets, liabilities, income and expenses, line by line (even if you own 80%).' }, { t: 'Eliminate the investment', d: 'Remove the parent’s “Investment in Sub” against the subsidiary’s equity at acquisition, recognising goodwill.' }, { t: 'Recognise NCI', d: 'Non-controlling interest = the outside shareholders’ share of the subsidiary’s net assets, shown within equity.' }, { t: 'Eliminate intra-group items', d: 'Intercompany balances, sales/purchases, dividends, and unrealised profit in inventory or assets.' }, { t: 'Uniform policies & dates', d: 'Align accounting policies and reporting dates across the group.' }] },
      { t: 'formula', html: 'Goodwill = Consideration + NCI − Fair value of net assets acquired' },
      { t: 'p', html: '<b>Example:</b> Max Holdings buys 80% of Wheelco for $900,000. Wheelco’s identifiable net assets at fair value: $1,000,000. NCI measured at its share of net assets (20% × 1,000,000 = $200,000). Goodwill = 900,000 + 200,000 − 1,000,000 = <b>$100,000</b>. (IFRS also allows NCI at fair value — “full goodwill”.) A negative result is a <b>bargain purchase gain</b> (after re-checking the numbers!).' },
      { t: 'h3', text: 'Unrealised profit' },
      { t: 'p', html: 'Wheelco sells wheels to the parent for $50,000 that cost $40,000. At year-end, the parent still holds a quarter of them. From the group’s view, nothing was sold to outsiders for that quarter, so remove the profit: 25% × $10,000 = $2,500.' },
      { t: 'entry', title: 'Consolidation adjustments', lines: [['Revenue (intercompany)', 50000, 0], ['Cost of Sales', 0, 50000]], narr: 'Eliminate intra-group sale' },
      { t: 'entry', lines: [['Cost of Sales', 2500, 0], ['Inventory', 0, 2500]], narr: 'Remove unrealised profit in closing inventory' },
      { t: 'h3', text: 'The equity method' },
      { t: 'p', html: 'Investment starts at cost, then increases by your share of the associate’s profit and decreases by dividends received. One line on the balance sheet (“Investment in associate”) and one line in the P&L (“Share of profit of associates”).' },

      { t: 'h', text: 'Foreign currency transactions' },
      { t: 'list', items: ['Every entity has a <b>functional currency</b> — the currency of its primary economic environment.', 'Record foreign transactions at the <b>spot rate</b> on the transaction date.', 'At each reporting date, retranslate <b>monetary items</b> (cash, receivables, payables, loans) at the <b>closing rate</b> → <b>unrealised</b> exchange gains/losses in P&L.', '<b>Non-monetary items</b> at historical cost (inventory, PPE, prepaid) are not retranslated.', 'On settlement, differences become <b>realised</b> gains/losses.'] },
      { t: 'widget', name: 'fx' },
      { t: 'h3', text: 'Translating a foreign subsidiary' },
      { t: 'p', html: 'To consolidate Wheelco Europe (functional currency EUR) into a USD group: assets and liabilities at the <b>closing rate</b>; income and expenses at <b>transaction-date or average rates</b>; equity at historical rates. The balancing difference goes to <b>OCI</b> (foreign currency translation reserve) and is recycled to profit when the subsidiary is sold.' },
      { t: 'odoo', title: 'Multi-company & multi-currency in Odoo', html: '<ul><li><b>Multi-currency</b>: activate currencies, enable automatic rate updates; invoices in foreign currency post at the day’s rate; on payment, Odoo posts the <b>exchange difference</b> automatically to the Exchange Difference journal (gain/loss accounts set in Settings). Unrealised gains/losses can be booked via the <b>Unrealized Currency Gains/Losses</b> report adjustment.</li><li><b>Multi-company</b>: separate companies in one database with shared or separate charts; <b>inter-company rules</b> can mirror a sale in one company as a purchase in the other. Consolidation tooling depends on version (dedicated app in some versions; otherwise reports per company + eliminations).</li></ul>' },
      { t: 'bullets', items: ['Subsidiary (control) → full consolidation; associate/JV → equity method.', 'Goodwill = consideration + NCI − FV of net assets.', 'Eliminate intra-group balances, transactions and unrealised profit.', 'Monetary items retranslated at closing rate; non-monetary stay at historical rate.', 'Translation differences of foreign operations go to OCI.'] },
    ],
    quiz: [
      { q: 'A holding giving significant influence (but not control) is usually accounted for using…', o: ['Full consolidation', 'The equity method', 'Fair value through P&L only', 'Proportionate consolidation'], a: 1, e: 'Associates use the equity method.' },
      { q: 'Consideration 600k, NCI 150k, FV of net assets 700k. Goodwill?', o: ['50k', '100k', '−50k', '150k'], a: 0, e: '600 + 150 − 700 = 50k.' },
      { q: 'A subsidiary owned 75% is consolidated by including ___ of its assets.', o: ['75%', '100%', '25%', '0%'], a: 1, e: 'All assets and liabilities; NCI shows the outside share.' },
      { q: 'Which item is retranslated at the closing rate?', o: ['Inventory at cost', 'Equipment', 'Foreign-currency receivable', 'Prepaid rent'], a: 2, e: 'Monetary items are retranslated.' },
      { q: 'Invoice €1,000 at 1.10; paid at 1.15 ($ per €). The seller records…', o: ['$50 loss', '$50 gain', 'No difference', '$100 gain'], a: 1, e: 'Received $1,150 vs $1,100 booked.' },
      { q: 'Translation differences on consolidating a foreign subsidiary go to…', o: ['Revenue', 'OCI / translation reserve', 'Cost of sales', 'Goodwill'], a: 1, e: 'IAS 21: recognised in OCI.' },
    ],
    cards: [
      ['Control (IFRS 10)', 'Power over the investee, exposure to variable returns and ability to use power to affect returns.'],
      ['Goodwill', 'Consideration + NCI − fair value of identifiable net assets.'],
      ['Non-controlling interest', 'Equity in a subsidiary not attributable to the parent.'],
      ['Equity method', 'Investment at cost adjusted for share of profits and dividends.'],
      ['Functional currency', 'Currency of the primary economic environment of an entity.'],
      ['Monetary item', 'Units of currency held or to be received/paid (cash, receivables, payables, loans).'],
    ],
  });

